(()=>{'use strict';const status=document.querySelector('.station-status'),host=status||document.querySelector('.work-bar');if(!host)return;const box=document.createElement('div');box.className='device-health';box.hidden=true;box.setAttribute('role','status');if(status)host.insertBefore(box,host.querySelector('.station-clock'));else host.append(box);let busy=false;
 async function refresh(){if(document.hidden||busy)return;busy=true;try{const r=await fetch('/api/admin/desk-health',{cache:'no-store'});if(r.status===401){box.hidden=true;return;}if(!r.ok)throw Error();const d=await r.json();box.replaceChildren();box.removeAttribute('data-state');box.removeAttribute('title');for(const item of [d.printer,d.terminal]){const span=document.createElement('span');span.dataset.state=item.state;const label=item===d.printer?'Принтер':'Терминал';span.textContent=item.state==='ok'?'● '+label:status?'! '+label:(document.body.classList.contains('pos-redesign')||document.querySelector('link[href^="/admin/pos-chrome.css"]'))?'! '+label+(item.state==='unconfigured'?' · не настроен':' · нет связи'):'! '+item.message;span.title=item.message+'. '+d.note;span.setAttribute('aria-label',span.title);box.append(span);}box.hidden=false;}catch{box.hidden=false;box.dataset.state='error';box.textContent=status?'! Оборудование':'Статус оборудования не обновлён — проверьте связь.';box.title='Статус оборудования не обновлён — проверьте связь.';}finally{busy=false;}}
 refresh();setInterval(refresh,60000);document.addEventListener('visibilitychange',refresh);
})();
